#!/usr/bin/env node
/**
 * import-contributors — pull cloudemu's GitHub contributors and generate the
 * data the Contributors page renders (lib/contributors.generated.ts).
 *
 * Source of truth is the product repo (github.com/stackshy/cloudemu). Bots and
 * anonymous entries are dropped; the rest are sorted by commit count. Re-run
 * after notable contribution changes and commit the regenerated file.
 *
 * Usage:  node scripts/import-contributors.mjs [--repo owner/name]
 */
import { writeFileSync } from 'node:fs';
import { execSync } from 'node:child_process';

const repoArg = process.argv.indexOf('--repo');
const REPO = repoArg >= 0 ? process.argv[repoArg + 1] : 'stackshy/cloudemu';

const raw = execSync(`gh api 'repos/${REPO}/contributors?per_page=100'`, { maxBuffer: 32 * 1024 * 1024 }).toString();

const people = JSON.parse(raw)
  .filter((c) => c.type === 'User' && !/\[bot\]$/.test(c.login))
  .map((c) => ({
    login: c.login,
    avatar: c.avatar_url,
    contributions: c.contributions,
    url: c.html_url,
  }))
  .sort((a, b) => b.contributions - a.contributions);

const total = people.reduce((n, p) => n + p.contributions, 0);

const out = `// GENERATED by scripts/import-contributors.mjs — do not edit by hand.
// Source: github.com/${REPO} contributors. Re-run the script to refresh.

export interface Contributor {
  login: string;
  avatar: string;
  contributions: number;
  url: string;
}

export const CONTRIBUTORS: Contributor[] = ${JSON.stringify(people, null, 2)};

export const TOTAL_CONTRIBUTIONS = ${total};
`;

writeFileSync(new URL('../lib/contributors.generated.ts', import.meta.url), out);
console.log(`wrote ${people.length} contributors (${total} contributions) from ${REPO}`);
